"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type FocusEvent, type MouseEventHandler, type PointerEvent, type ReactNode, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for an arrow link. */
export interface ArrowLinkProps {
  href: string;
  /** The link text. Say where the link goes, for example "Read the changelog". */
  children: ReactNode;
  onClick?: MouseEventHandler<HTMLAnchorElement>;
  target?: string;
  rel?: string;
  className?: string;
}

// One ease-out for the chevron and its stem. No overshoot: the arrow points, it does not bounce.
const NUDGE: Transition = { duration: 0.35, ease: [0.22, 1, 0.36, 1] };
const INSTANT: Transition = { duration: 0 };

// A tap also focuses the link. Only keyboard focus should hold the arrow out.
function focusIsVisible(element: Element) {
  try {
    return element.matches(":focus-visible");
  } catch {
    // An engine without :focus-visible throws on the selector. Treat every focus as visible there.
    return true;
  }
}

/**
 * A text link that ends in a chevron. On hover and on keyboard focus the
 * chevron slides right and a stem draws in behind it, so it becomes an arrow.
 */
export function ArrowLink({ href, children, onClick, target, rel, className }: ArrowLinkProps) {
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [pressed, setPressed] = useState(false);
  const reduceMotion = useReducedMotion();
  const open = hovered || focused || pressed;
  const transition = reduceMotion ? INSTANT : NUDGE;

  return (
    <a
      href={href}
      target={target}
      rel={rel}
      onClick={onClick}
      data-open={open || undefined}
      // A touch has no hover: its synthetic one would stick until the next tap.
      onPointerEnter={(event: PointerEvent) => {
        if (event.pointerType !== "touch") setHovered(true);
      }}
      onPointerLeave={() => {
        setHovered(false);
        setPressed(false);
      }}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerCancel={() => setPressed(false)}
      onFocus={(event: FocusEvent<HTMLElement>) => setFocused(focusIsVisible(event.currentTarget))}
      onBlur={() => setFocused(false)}
      className={cn(
        "inline-flex min-h-11 cursor-pointer touch-manipulation items-center gap-1 rounded-md text-sm font-medium text-foreground outline-none sm:min-h-9",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className,
      )}
    >
      {children}
      <svg
        aria-hidden="true"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
        strokeLinejoin="round"
        className={cn(
          "size-4 shrink-0 motion-safe:transition-colors motion-safe:duration-150",
          open ? "text-foreground" : "text-muted-foreground",
        )}
      >
        {/* The stem stays where it is and grows; the chevron carries the movement. */}
        <motion.path
          d="M2.5 8h9"
          initial={false}
          animate={{ pathLength: open ? 1 : 0, opacity: open ? 1 : 0 }}
          transition={transition}
        />
        <motion.path
          d="M5.5 3.75 9.75 8 5.5 12.25"
          initial={false}
          animate={{ x: open ? 2.75 : 0 }}
          transition={transition}
        />
      </svg>
    </a>
  );
}
